import{_ as h,C as n,o as i,c as l,aj as a,E as r,j as e,a as o}from"./framework.js";const m=JSON.parse('{"title":"AI Claw / AI Chat | Product | Documentation","description":"AI Claw / AI Chat in Kooboo: 常用 tab 取值：chat（默认，可不写）、fix、task、data、design、service、setting。","frontmatter":{"title":"AI Claw / AI Chat | Product | Documentation","description":"AI Claw / AI Chat in Kooboo: 常用 tab 取值：chat（默认，可不写）、fix、task、data、design、service、setting。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/ai-chat.html"}]]},"headers":[],"relativePath":"zh/product/ai-chat.md","filePath":"product/ai-chat.md","lastUpdated":1786094386000}'),s={name:"zh/product/ai-chat.md"};function c(b,t,g,_,A,I){const d=n("DocImage");return i(),l("div",null,[t[0]||(t[0]=a('<h1 id="ai-claw-ai-chat" tabindex="-1">AI Claw / AI Chat <a class="header-anchor" href="#ai-claw-ai-chat" aria-label="Permalink to &quot;AI Claw / AI Chat&quot;">​</a></h1><blockquote><p>用自然语言描述目标，在站点级 AI 工作台中对话、预览站点、管理自动化任务，并在需要时转交人工协助。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>顶部入口</td><td>进入站点后台后，点击顶部 <strong>AI</strong> 按钮</td></tr><tr><td>深链</td><td><code>/_Admin/ai-chat/overview?SiteId={站点GUID}</code></td></tr><tr><td>指定左侧面板</td><td><code>/_Admin/ai-chat/overview?SiteId={站点GUID}&amp;tab={面板}</code></td></tr><tr><td>数据子菜单</td><td>再加 <code>&amp;submenu={子项}</code>，例如 <code>submenu=content-model</code></td></tr><tr><td>前端路由</td><td><code>/ai-chat/overview</code></td></tr><tr><td>页面层级</td><td>站点级页面，必须带 <code>SiteId</code></td></tr></tbody></table><p>常用 <code>tab</code> 取值：<code>chat</code>（默认，可不写）、<code>fix</code>、<code>task</code>、<code>data</code>、<code>design</code>、<code>service</code>、<code>setting</code>。</p><p>AI Claw 与右下角 <a href="./ai-floating-assistant.html">AI 悬浮助手</a> 共用对话与工具能力。区别在于：Claw 是独立工作台，对话区左侧可切换会话 / 任务 / 数据 / 设计等面板，右侧是可切换的站点工作区（预览、代码、媒体、蓝图）。</p>',6)),r(d,{src:"/product/ai-chat/ai-chat-overview.png",alt:"AI Claw：左侧对话、右侧实时站点预览工作区",width:"1120"}),t[1]||(t[1]=a('<h2 id="页面结构" tabindex="-1">页面结构 <a class="header-anchor" href="#页面结构" aria-label="Permalink to &quot;页面结构&quot;">​</a></h2><p>界面通常分为四块：</p><table tabindex="0"><thead><tr><th>区域</th><th>怎么用</th></tr></thead><tbody><tr><td>顶部栏</td><td>切换站点、返回 <strong>AI 创作</strong>、打开顶部 <strong>AI</strong> 入口</td></tr><tr><td>最左侧图标栏</td><td>切换会话历史、固定例行事项、全部任务、数据、设计、人工帮助、设置；可用 <code>Cmd/Ctrl + B</code> 展开或收起旁边的列表面板</td></tr><tr><td>中间对话区</td><td>与 <strong>Kooboo 自助智能体</strong> 对话；标题栏可打开 <strong>人工帮助</strong></td></tr><tr><td>右侧工作区</td><td>实时预览站点，或切换到代码、媒体库、应用蓝图</td></tr></tbody></table><p>默认进入会话模式时，列表面板可能收起，只保留图标栏与对话区。点击图标栏中的会话、固定事项、任务等入口，或按 <code>Cmd/Ctrl + B</code>，可展开左侧列表面板。</p><h2 id="对话区" tabindex="-1">对话区 <a class="header-anchor" href="#对话区" aria-label="Permalink to &quot;对话区&quot;">​</a></h2><p>中间对话区是主要操作面。</p><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td>输入框</td><td>输入自然语言目标，例如“检查这个站点的首页内容是否完整”</td></tr><tr><td>模型选择</td><td>选择 Provider 与模型；部分模型还可设置推理强度（如低 / 中 / 高 / 超高）</td></tr><tr><td>执行策略</td><td>快捷切换 <strong>每次确认</strong>、<strong>仅自动执行允许项</strong>、<strong>自动执行</strong>；可从下拉菜单进入完整设置</td></tr><tr><td>图片上传</td><td>给 AI 添加截图或图片上下文</td></tr><tr><td>发送</td><td>点击发送按钮，或按设置中的发送快捷键（默认 <code>Enter</code>，也可改为 <code>Cmd/Ctrl + Enter</code>）</td></tr><tr><td>停止</td><td>回答生成中时，发送按钮会变成停止</td></tr></tbody></table><p>如果 AI 准备执行写入、修改代码或调用工具，界面会展示确认项。站点能调用哪些 MCP、AI 函数和内置工具，由 <a href="/kb-docs/zh/cms/settings/ai-service.html">CMS：AI 服务</a> 决定。</p><p>对话进行中还可能出现：</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>当前待办</td><td>AI 把多步目标拆成待办列表，并在对话旁跟踪完成情况</td></tr><tr><td>下一步推荐</td><td>一轮结束后给出可继续的方向，可直接发送或填入输入框</td></tr><tr><td>建站进度</td><td>建站类任务会显示里程碑进度</td></tr></tbody></table><h2 id="右侧工作区" tabindex="-1">右侧工作区 <a class="header-anchor" href="#右侧工作区" aria-label="Permalink to &quot;右侧工作区&quot;">​</a></h2><p>右侧工作区与对话并排，方便边聊边看结果。顶部可用工作区模式切换：</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th></tr></thead><tbody><tr><td>浏览器</td><td><strong>实时站点预览</strong>：地址栏跳转页面、切换桌面 / 平板 / 手机视口、选择页面元素并添加注释后发给 AI</td></tr><tr><td>代码</td><td>浏览站点资源树并预览源码，可引用代码或跳到 <a href="./developer-mode.html">开发者模式</a></td></tr><tr><td>媒体库</td><td>在有权限时查看站点媒体资源</td></tr><tr><td>应用蓝图</td><td>站点存在应用蓝图时，查看结构并就蓝图内容继续与 AI 讨论</td></tr></tbody></table>',13)),r(d,{src:"/product/ai-chat/workspace-code.png",alt:"AI Claw 右侧工作区：站点代码树与源码预览",width:"1120"}),t[2]||(t[2]=a('<p>浏览器预览底部还可打开：</p><table tabindex="0"><thead><tr><th>工具</th><th>说明</th></tr></thead><tbody><tr><td>运行日志</td><td>查看预览页捕获的错误、警告与普通日志，并可让 AI 排查</td></tr><tr><td>网络请求</td><td>查看失败、超时或异常请求，并可让 AI 排查</td></tr><tr><td>Iframe 预览说明</td><td>了解内嵌预览的限制；完整设备能力、登录态、支付跳转等仍以新标签页打开站点为准</td></tr></tbody></table><p>AI 正在生成页面时，预览区可能显示构建进度；首个页面就绪后会自动展示预览。工作区可拖动分隔条调整宽度，或从对话区标题栏收起 / 展开。</p><h2 id="左侧面板" tabindex="-1">左侧面板 <a class="header-anchor" href="#左侧面板" aria-label="Permalink to &quot;左侧面板&quot;">​</a></h2><h3 id="会话历史" tabindex="-1">会话历史 <a class="header-anchor" href="#会话历史" aria-label="Permalink to &quot;会话历史&quot;">​</a></h3><p>点击会话历史图标并展开面板后，可管理当前站点的对话。</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>总览会话 / 全部对话</td><td>切换只看总览会话，或查看全部会话</td></tr><tr><td>开启新对话</td><td>新建空白会话</td></tr><tr><td>导入</td><td>导入会话文件</td></tr><tr><td>重命名 / 删除</td><td>管理历史会话</td></tr></tbody></table><h3 id="固定例行事项" tabindex="-1">固定例行事项 <a class="header-anchor" href="#固定例行事项" aria-label="Permalink to &quot;固定例行事项&quot;">​</a></h3><p>把一段 AI 指令设成一次性或循环执行的自动化任务。</p>',9)),r(d,{src:"/product/ai-chat/fixed-tasks.png",alt:"AI Claw 固定例行事项：空状态与新增按钮",width:"1120"}),t[3]||(t[3]=e("p",null,[o("点击面板右上角 "),e("strong",null,"+"),o("，打开新建弹窗。标题为 "),e("strong",null,"新建自动化任务"),o("；也可点 "),e("strong",null,"使用模板"),o(" 从电商、内容巡检、开发质量、站点维护等模板开始。")],-1)),r(d,{src:"/product/ai-chat/fixed-task-dialog.png",alt:"新建自动化任务：任务名称、提示词、执行方式、间隔、开始时间、模型和状态",width:"720"}),t[4]||(t[4]=a('<table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>任务名称</td><td>便于识别的名称，建议写清对象和目标</td></tr><tr><td>提示词</td><td>AI 要检查、生成、提醒或调用的完整说明</td></tr><tr><td>执行方式</td><td>单次或循环</td></tr><tr><td>重复间隔</td><td>循环时填写数量与单位（天、小时、分钟等）</td></tr><tr><td>开始时间</td><td>首次或下次计划执行时间</td></tr><tr><td>模型</td><td>该自动化任务使用的 AI 模型</td></tr><tr><td>状态</td><td>未启用或已启用；未准备好前先保持未启用</td></tr></tbody></table><p>保存后可在列表中编辑、删除或立即运行；任务正在运行时界面会避免重复触发。</p><h3 id="全部任务列表" tabindex="-1">全部任务列表 <a class="header-anchor" href="#全部任务列表" aria-label="Permalink to &quot;全部任务列表&quot;">​</a></h3><p>展示 AI 自动化任务的运行记录。</p>',4)),r(d,{src:"/product/ai-chat/task-list.png",alt:"AI Claw 全部任务列表：按任务状态筛选，右侧查看执行记录",width:"1120"}),t[5]||(t[5]=a('<table tabindex="0"><thead><tr><th>筛选</th><th>说明</th></tr></thead><tbody><tr><td>全部</td><td>查看所有任务记录</td></tr><tr><td>等待中</td><td>尚未开始执行</td></tr><tr><td>运行中</td><td>正在执行</td></tr><tr><td>已完成</td><td>已完成任务</td></tr><tr><td>失败</td><td>执行失败，便于排查</td></tr></tbody></table><p>从左侧选中一条任务后，中间会显示完整执行记录。对可继续的任务，界面会提供 <strong>继续会话</strong>，把任务日志带入新对话继续处理。</p><h3 id="数据" tabindex="-1">数据 <a class="header-anchor" href="#数据" aria-label="Permalink to &quot;数据&quot;">​</a></h3><p>在 AI 工作台内直接查看或维护内容与电商数据，无需离开对话上下文。</p>',4)),r(d,{src:"/product/ai-chat/data-content.png",alt:"AI Claw 数据面板：内容模型、内容数据、产品类型、分类与产品",width:"1120"}),t[6]||(t[6]=a('<table tabindex="0"><thead><tr><th>分组</th><th>子项</th></tr></thead><tbody><tr><td>内容</td><td>内容模型、内容数据</td></tr><tr><td>电商</td><td>产品类型、分类、产品</td></tr></tbody></table><p>深链示例：<code>/_Admin/ai-chat/overview?SiteId={站点GUID}&amp;tab=data&amp;submenu=content-model</code>。</p><h3 id="设计" tabindex="-1">设计 <a class="header-anchor" href="#设计" aria-label="Permalink to &quot;设计&quot;">​</a></h3><p>查看和调整站点设计变量（颜色、字体、圆角、间距、阴影等）。若尚未初始化，可先 <strong>初始化设计变量</strong>，再保存修改。</p>',4)),r(d,{src:"/product/ai-chat/design.png",alt:"AI Claw 设计参数面板：初始化设计变量",width:"1120"}),t[7]||(t[7]=a('<h3 id="人工帮助" tabindex="-1">人工帮助 <a class="header-anchor" href="#人工帮助" aria-label="Permalink to &quot;人工帮助&quot;">​</a></h3><p>在支持的环境中选择专家、提交协助工单，并跟进消息与验收状态。也可从对话区标题栏的 <strong>人工帮助</strong> 直接发起。</p><p>人工帮助可能涉及专家服务、支付和验收；账户余额、订单和支付核对仍回到 <a href="./console/balance.html">控制台：余额</a> 与 <a href="./console/orders.html">控制台：订单</a>。</p><h3 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h3><p>打开 <strong>AI Chat 设置</strong>，管理个人偏好与站点级执行策略。</p>',5)),r(d,{src:"/product/ai-chat/settings.png",alt:"AI Chat 设置：个人偏好与站点执行策略",width:"1120"}),t[8]||(t[8]=a('<table tabindex="0"><thead><tr><th>分区</th><th>作用范围</th><th>内容</th></tr></thead><tbody><tr><td>个人偏好</td><td>当前浏览器</td><td>发送快捷键、AI 工作期间再次发送（加入队列 / 中断并发送）、新站点默认执行策略、完成通知</td></tr><tr><td>站点执行策略</td><td>全站共享</td><td><strong>每次确认</strong>、<strong>仅自动执行允许项</strong>、<strong>自动执行</strong>；允许项模式下可管理可自动执行的 function</td></tr></tbody></table><p>修改站点执行策略需要相应 AI 编辑权限。对话区输入框旁的执行策略按钮可快速切换，也可跳转到本页做完整配置。</p><h2 id="使用前先确认" tabindex="-1">使用前先确认 <a class="header-anchor" href="#使用前先确认" aria-label="Permalink to &quot;使用前先确认&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>位置</th></tr></thead><tbody><tr><td>组织级 AI Provider 是否已配置</td><td><a href="./console/ai-config.html">控制台：AI 配置</a></td></tr><tr><td>账户余额是否足够</td><td><a href="./console/balance.html">控制台：余额</a></td></tr><tr><td>站点是否启用 MCP 或 AI 函数</td><td><a href="/kb-docs/zh/cms/settings/ai-service.html">CMS：AI 服务</a></td></tr><tr><td>执行策略是否符合环境风险</td><td>AI Claw -&gt; 设置，或输入框旁的执行策略按钮</td></tr><tr><td>是否需要让 AI 引用当前代码</td><td>右侧 <strong>代码</strong> 工作区引用，或 <a href="./developer-mode.html">开发者模式</a> 中右键资源标签 <strong>添加到对话</strong></td></tr></tbody></table><h2 id="与-ai-悬浮助手的区别" tabindex="-1">与 AI 悬浮助手的区别 <a class="header-anchor" href="#与-ai-悬浮助手的区别" aria-label="Permalink to &quot;与 AI 悬浮助手的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>AI Claw / AI Chat</th><th>AI 悬浮助手</th></tr></thead><tbody><tr><td>独立工作台：对话 + 左侧面板 + 右侧站点工作区</td><td>浮在当前后台页面右下角，适合边操作边问</td></tr><tr><td>适合建站、预览、看代码、跑固定任务、查任务日志</td><td>适合基于当前 CMS 页面上下文快速提问</td></tr><tr><td>进入后主要围绕 AI 工作台操作</td><td>保留当前 CMS 页面，不打断正在做的配置</td></tr></tbody></table><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>操作</th></tr></thead><tbody><tr><td>开始一段站点 AI 对话</td><td>站点后台 -&gt; 顶部 <strong>AI</strong> -&gt; 输入目标 -&gt; 选择模型与执行策略 -&gt; 发送</td></tr><tr><td>边对话边看前台效果</td><td>保持右侧 <strong>浏览器</strong> 工作区展开 -&gt; 让 AI 修改后刷新预览</td></tr><tr><td>给预览页提修改意见</td><td>预览工具栏选择元素 -&gt; 添加注释 -&gt; 填入输入框或直接发送</td></tr><tr><td>排查预览报错</td><td>打开 <strong>运行日志</strong> 或 <strong>网络请求</strong> -&gt; <strong>让 AI 排查</strong></td></tr><tr><td>设置定期巡检</td><td>固定例行事项 -&gt; <strong>+</strong> -&gt; 填名称、提示词、周期与模型 -&gt; 创建</td></tr><tr><td>排查任务运行结果</td><td>全部任务列表 -&gt; 选择状态筛选 -&gt; 点击记录查看日志</td></tr><tr><td>在工作台内改内容或商品</td><td>数据面板 -&gt; 选择内容 / 电商子项</td></tr><tr><td>调整设计变量</td><td>设计面板 -&gt; 初始化或编辑变量 -&gt; 保存</td></tr><tr><td>需要人工协助</td><td>标题栏 <strong>人工帮助</strong>，或左侧人工帮助面板</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./ai-floating-assistant.html">AI 悬浮助手</a></td><td>当前页面上下文助手</td></tr><tr><td><a href="./console/ai-config.html">控制台：AI 配置</a></td><td>组织级 AI Provider API Key</td></tr><tr><td><a href="./console/balance.html">控制台：余额</a></td><td>余额与充值入口</td></tr><tr><td><a href="/kb-docs/zh/cms/settings/ai-service.html">CMS：AI 服务</a></td><td>MCP、AI 函数、向量搜索与站点 AI 设置</td></tr><tr><td><a href="./developer-mode.html">开发者模式</a></td><td>多资源编辑、调试与代码引用入口</td></tr></tbody></table>',10))])}const u=h(s,[["render",c]]);export{m as __pageData,u as default};
